import math

def sigma(m):
    """Calculates the sum of divisors function sigma(m)."""
    if m == 1:
        return 1

    divisors = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.add(i)
            divisors.add(m // i)
    return sum(divisors)

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

# Investigate small values of m > 1
# We will search up to m = 200 to get some initial examples.
max_m = 200
found_m = []

for m in range(2, max_m + 1):
    s_m = sigma(m)
    if is_square(s_m):
        found_m.append((m, s_m))

print(f"Found {len(found_m)} values of m <= {max_m} such that sigma(m) is a perfect square:")
for m, s in found_m:
    print(f"m = {m}, sigma(m) = {s}")

import math
from itertools import permutations

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def sum_of_divisors(m):
    s = 0
    for d in get_divisors(m):
        s += d
    return s

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_m(m):
    divisors = get_divisors(m)
    total_sum = sum_of_divisors(m)

    # Necessary condition 1: Total sum must be a perfect square
    if not is_perfect_square(total_sum):
        return False

    # Check for permutations
    for p in permutations(divisors):
        current_sum = 0
        all_partial_sums_square = True
        for i in range(len(p)):
            current_sum += p[i]
            if not is_perfect_square(current_sum):
                all_partial_sums_square = False
                break

        if all_partial_sums_square:
            return True

    return False

results = {}
for m in range(2, 21):
    results[m] = check_m(m)

print("Results (m: True/False):")
for m, result in results.items():
    print(f"{m}: {result}")
